package auth_test

import (
	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"

	"github.com/Infisical/infisical-issuer/api/v1alpha1"
	"github.com/Infisical/infisical-issuer/internal/auth"
)

var _ = Describe("Kubernetes Auth", func() {
	const (
		identityIDSecretName = "k8s-identity-id"
		namespace            = "default"
		secretKey            = "value"
	)

	It("should fail when .spec.authentication.kubernetes is nil", func() {
		provider := auth.NewKubernetesAuth(k8sClient)
		spec := newIssuerSpec(v1alpha1.AuthMethodKubernetes)

		err := provider.Validate(ctx, spec, namespace)
		Expect(err).To(HaveOccurred())
		Expect(err.Error()).To(ContainSubstring(".spec.authentication.kubernetes is not set"))
	})

	It("should fail when serviceAccountRef name is empty", func() {
		provider := auth.NewKubernetesAuth(k8sClient)
		spec := newIssuerSpec(v1alpha1.AuthMethodKubernetes)
		spec.Authentication.Kubernetes = &v1alpha1.KubernetesAuthConfig{
			ServiceAccountRef: v1alpha1.NamespacedName{Name: "", Namespace: namespace},
		}

		err := provider.Validate(ctx, spec, namespace)
		Expect(err).To(HaveOccurred())
		Expect(err.Error()).To(ContainSubstring("serviceAccountRef requires a name"))
	})

	It("should fail when the identity id secret does not exist", func() {
		provider := auth.NewKubernetesAuth(k8sClient)
		spec := newIssuerSpec(v1alpha1.AuthMethodKubernetes)
		spec.Authentication.Kubernetes = &v1alpha1.KubernetesAuthConfig{
			ServiceAccountRef: v1alpha1.NamespacedName{Name: "my-sa", Namespace: namespace},
			IdentityIDRef:     v1alpha1.SecretReference{Name: identityIDSecretName, Namespace: namespace, Key: secretKey},
		}

		err := provider.Validate(ctx, spec, namespace)
		Expect(err).To(HaveOccurred())
		Expect(err.Error()).To(ContainSubstring("unable to fetch secret"))
	})

	It("should succeed when serviceAccountRef and the identity id secret are set", func() {
		createSecret(identityIDSecretName, namespace, map[string][]byte{secretKey: []byte("my-identity-id")})
		DeferCleanup(func() { deleteSecret(identityIDSecretName, namespace) })

		provider := auth.NewKubernetesAuth(k8sClient)
		spec := newIssuerSpec(v1alpha1.AuthMethodKubernetes)
		spec.Authentication.Kubernetes = &v1alpha1.KubernetesAuthConfig{
			ServiceAccountRef: v1alpha1.NamespacedName{Name: "my-sa", Namespace: namespace},
			IdentityIDRef:     v1alpha1.SecretReference{Name: identityIDSecretName, Namespace: namespace, Key: secretKey},
		}

		Expect(provider.Validate(ctx, spec, namespace)).To(Succeed())
	})
})

package cache_test

import (
	"testing"
	"time"

	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"

	infisicalSdk "github.com/infisical/go-sdk"

	"github.com/Infisical/infisical-issuer/internal/cache"
	"github.com/Infisical/infisical-issuer/internal/model"
)

func TestCache(t *testing.T) {
	RegisterFailHandler(Fail)
	RunSpecs(t, "Cache Suite")
}

func newAuthResult(token string) *model.AuthenticationResult {
	return &model.AuthenticationResult{
		MachineIdentity: infisicalSdk.MachineIdentityCredential{AccessToken: token},
	}
}

var _ = Describe("AuthCache", func() {
	var (
		authCache *cache.AuthCache
		key       cache.ClientCacheKey
	)

	BeforeEach(func() {
		key = cache.ClientCacheKey{Name: "test-issuer", Namespace: "default"}
	})

	AfterEach(func() {
		if authCache != nil {
			authCache.Cleanup()
		}
	})

	Describe("happy path", func() {
		BeforeEach(func() {
			var err error
			authCache, err = cache.NewAuthCache()
			Expect(err).NotTo(HaveOccurred())
		})

		It("should store and retrieve a value", func() {
			authCache.Set(key, newAuthResult("token-1"), 30*time.Second)

			result, found := authCache.Get(key)
			Expect(found).To(BeTrue())
			Expect(result.AccessToken()).To(Equal("token-1"))
		})

		It("should return false for a key that was never set", func() {
			_, found := authCache.Get(key)
			Expect(found).To(BeFalse())
		})

		It("should not cache a value with a non-positive TTL", func() {
			Expect(authCache.Set(key, newAuthResult("zero-ttl"), 0)).To(BeFalse())
			_, found := authCache.Get(key)
			Expect(found).To(BeFalse())

			Expect(authCache.Set(key, newAuthResult("negative-ttl"), -5*time.Second)).To(BeFalse())
			_, found = authCache.Get(key)
			Expect(found).To(BeFalse())
		})

		It("should treat keys that differ only by generation as distinct", func() {
			gen1 := cache.ClientCacheKey{Name: "iss", Namespace: "default", Generation: 1}
			gen2 := cache.ClientCacheKey{Name: "iss", Namespace: "default", Generation: 2}

			Expect(authCache.Set(gen1, newAuthResult("old"), 30*time.Second)).To(BeTrue())

			_, found := authCache.Get(gen2)
			Expect(found).To(BeFalse(), "a new generation must not hit the prior generation's token")

			result, found := authCache.Get(gen1)
			Expect(found).To(BeTrue())
			Expect(result.AccessToken()).To(Equal("old"))
		})

		It("should delete a cached entry", func() {
			authCache.Set(key, newAuthResult("token-1"), 30*time.Second)

			authCache.Delete(key)

			_, found := authCache.Get(key)
			Expect(found).To(BeFalse())
		})
	})

	Describe("TTL expiration", func() {
		BeforeEach(func() {
			var err error
			authCache, err = cache.NewAuthCache()
			Expect(err).NotTo(HaveOccurred())
		})

		It("should not find a key after its TTL expires", func() {
			authCache.Set(key, newAuthResult("short-lived"), 2*time.Second)

			result, found := authCache.Get(key)
			Expect(found).To(BeTrue())
			Expect(result.AccessToken()).To(Equal("short-lived"))

			time.Sleep(3 * time.Second)

			_, found = authCache.Get(key)
			Expect(found).To(BeFalse())
		})
	})

	Describe("minTTLThreshold", func() {
		BeforeEach(func() {
			var err error
			authCache, err = cache.NewAuthCache(cache.WithMinTTLThreshold(5 * time.Second))
			Expect(err).NotTo(HaveOccurred())
		})

		It("should not cache a value when the TTL is below the threshold", func() {
			authCache.Set(key, newAuthResult("below-threshold"), 2*time.Second)

			_, found := authCache.Get(key)
			Expect(found).To(BeFalse())
		})

		It("should cache a value when the TTL meets the threshold", func() {
			authCache.Set(key, newAuthResult("above-threshold"), 10*time.Second)

			result, found := authCache.Get(key)
			Expect(found).To(BeTrue())
			Expect(result.AccessToken()).To(Equal("above-threshold"))
		})
	})
})

package auth

import (
	"context"
	"fmt"

	"github.com/Infisical/infisical-issuer/api/v1alpha1"
	"github.com/Infisical/infisical-issuer/internal/model"
	"github.com/Infisical/infisical-issuer/internal/util"
	"sigs.k8s.io/controller-runtime/pkg/client"
)

type kubernetesAuth struct {
	client client.Client
}

func NewKubernetesAuth(c client.Client) Strategy {
	return &kubernetesAuth{client: c}
}

func (k *kubernetesAuth) Validate(ctx context.Context, spec *v1alpha1.IssuerSpec, resourceNamespace string) error {
	cfg := spec.Authentication.Kubernetes
	if cfg == nil {
		return fmt.Errorf("%w: method is %q but .spec.authentication.kubernetes is not set", model.ErrInvalidIssuerSpec, v1alpha1.AuthMethodKubernetes)
	}
	if cfg.ServiceAccountRef.Name == "" {
		return fmt.Errorf("%w: .spec.authentication.kubernetes.serviceAccountRef requires a name", model.ErrInvalidIssuerSpec)
	}
	if _, err := util.ResolveSecretReference(ctx, k.client, cfg.IdentityIDRef, resourceNamespace, ".spec.authentication.kubernetes.identityIdRef"); err != nil {
		return err
	}
	return nil
}

func (k *kubernetesAuth) Authenticate(ctx context.Context, conn *model.InfisicalConnection, spec *v1alpha1.IssuerSpec, resourceNamespace string) (*model.AuthenticationResult, error) {
	cfg := spec.Authentication.Kubernetes
	if cfg == nil {
		return nil, fmt.Errorf("%w: .spec.authentication.kubernetes is nil", model.ErrInvalidIssuerSpec)
	}

	identityID, err := util.ResolveSecretReference(ctx, k.client, cfg.IdentityIDRef, resourceNamespace, ".spec.authentication.kubernetes.identityIdRef")
	if err != nil {
		return nil, err
	}

	token, err := util.MintServiceAccountToken(ctx, k.client, cfg.ServiceAccountRef, resourceNamespace, cfg.ServiceAccountTokenAudiences)
	if err != nil {
		return nil, err
	}

	cred, err := newSDKClient(ctx, conn).Auth().KubernetesRawServiceAccountTokenLogin(identityID, token)
	if err != nil {
		return nil, fmt.Errorf("unable to authenticate with Kubernetes Auth: %w", err)
	}

	return &model.AuthenticationResult{MachineIdentity: cred}, nil
}

package auth_test

import (
	. "github.com/onsi/gomega"
	corev1 "k8s.io/api/core/v1"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
