	"github.com/Infisical/infisical-issuer/api/v1alpha1"
)

func createSecret(name, namespace string, data map[string][]byte) {
	secret := &corev1.Secret{
		ObjectMeta: metav1.ObjectMeta{Name: name, Namespace: namespace},
		Data:       data,
	}
	Expect(k8sClient.Create(ctx, secret)).To(Succeed())
}

func deleteSecret(name, namespace string) {
	secret := &corev1.Secret{}
	Expect(k8sClient.Get(ctx, types.NamespacedName{Name: name, Namespace: namespace}, secret)).To(Succeed())
	Expect(k8sClient.Delete(ctx, secret)).To(Succeed())
}

func newIssuerSpec(method v1alpha1.AuthMethod) *v1alpha1.IssuerSpec {
	return &v1alpha1.IssuerSpec{
		URL:            "https://app.infisical.com",
		Application:    "app",
		Profile:        "profile",
		Authentication: v1alpha1.Authentication{Method: method},
	}
}

package auth_test

import (
	"context"
	"time"

	"github.com/go-logr/logr"
	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"

	infisicalSdk "github.com/infisical/go-sdk"

	"github.com/Infisical/infisical-issuer/api/v1alpha1"
	"github.com/Infisical/infisical-issuer/internal/auth"
	"github.com/Infisical/infisical-issuer/internal/cache"
	"github.com/Infisical/infisical-issuer/internal/model"
)

type fakeStrategy struct {
	callCount int
	result    *model.AuthenticationResult
}

func (f *fakeStrategy) Validate(_ context.Context, _ *v1alpha1.IssuerSpec, _ string) error {
	return nil
}

func (f *fakeStrategy) Authenticate(_ context.Context, _ *model.InfisicalConnection, _ *v1alpha1.IssuerSpec, _ string) (*model.AuthenticationResult, error) {
	f.callCount++
	return f.result, nil
}

var _ = Describe("Resolver registry", func() {
	It("should return an error for an unsupported auth method", func() {
		authCache, err := cache.NewAuthCache()
		Expect(err).ToNot(HaveOccurred())
		DeferCleanup(authCache.Cleanup)

		resolver := auth.NewResolver(k8sClient, authCache, logr.Discard())
		spec := newIssuerSpec("unsupported-method")

		err = resolver.Validate(ctx, spec, "default")
		Expect(err).To(HaveOccurred())
		Expect(err.Error()).To(ContainSubstring("unsupported authentication method"))
	})
})

var _ = Describe("Resolver cache behavior", func() {
	var (
		authCache *cache.AuthCache
		fake      *fakeStrategy
		resolver  *auth.Resolver
		spec      *v1alpha1.IssuerSpec
		key       cache.ClientCacheKey
	)

	BeforeEach(func() {
		var err error
		authCache, err = cache.NewAuthCache(cache.WithMinTTLThreshold(1 * time.Second))
		Expect(err).ToNot(HaveOccurred())

		fake = &fakeStrategy{
			result: &model.AuthenticationResult{
				MachineIdentity: infisicalSdk.MachineIdentityCredential{
					AccessToken: "fake-token",
					ExpiresIn:   600,
				},
			},
		}

		resolver = auth.NewResolverForTesting(authCache, map[v1alpha1.AuthMethod]auth.Strategy{
			v1alpha1.AuthMethodUniversal: fake,
		})

		spec = newIssuerSpec(v1alpha1.AuthMethodUniversal)
		key = cache.ClientCacheKey{Name: "issuer-1", Namespace: "default"}
	})

	AfterEach(func() {
		authCache.Cleanup()
	})

	It("should authenticate once and serve the second request from cache", func() {
		r1, err := resolver.Authenticate(ctx, spec, key, "default")
		Expect(err).NotTo(HaveOccurred())
		Expect(r1.AccessToken()).To(Equal("fake-token"))
		Expect(fake.callCount).To(Equal(1))

		r2, err := resolver.Authenticate(ctx, spec, key, "default")
		Expect(err).NotTo(HaveOccurred())
		Expect(r2.AccessToken()).To(Equal("fake-token"))
		Expect(fake.callCount).To(Equal(1))
	})

	It("should re-authenticate after the cache entry is invalidated", func() {
		_, err := resolver.Authenticate(ctx, spec, key, "default")
		Expect(err).NotTo(HaveOccurred())
		Expect(fake.callCount).To(Equal(1))

		resolver.Invalidate(key)

		_, err = resolver.Authenticate(ctx, spec, key, "default")
		Expect(err).NotTo(HaveOccurred())
		Expect(fake.callCount).To(Equal(2))
	})
})

package auth_test

import (
	"context"
	"os"
	"path/filepath"
	"testing"

	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"

	"k8s.io/client-go/kubernetes/scheme"
	"sigs.k8s.io/controller-runtime/pkg/client"
	"sigs.k8s.io/controller-runtime/pkg/envtest"
	logf "sigs.k8s.io/controller-runtime/pkg/log"
	"sigs.k8s.io/controller-runtime/pkg/log/zap"
)

var (
	ctx       context.Context
	cancel    context.CancelFunc
	testEnv   *envtest.Environment
	k8sClient client.Client
)

func TestAuth(t *testing.T) {
	RegisterFailHandler(Fail)
	RunSpecs(t, "Auth Suite")
}

var _ = BeforeSuite(func() {
	logf.SetLogger(zap.New(zap.WriteTo(GinkgoWriter), zap.UseDevMode(true)))

	ctx, cancel = context.WithCancel(context.TODO())

	By("bootstrapping test environment")
	testEnv = &envtest.Environment{}
	if dir := getFirstFoundEnvTestBinaryDir(); dir != "" {
		testEnv.BinaryAssetsDirectory = dir
	}

	cfg, err := testEnv.Start()
	Expect(err).NotTo(HaveOccurred())
	Expect(cfg).NotTo(BeNil())

	k8sClient, err = client.New(cfg, client.Options{Scheme: scheme.Scheme})
	Expect(err).NotTo(HaveOccurred())
	Expect(k8sClient).NotTo(BeNil())
})

var _ = AfterSuite(func() {
	By("tearing down the test environment")
	cancel()
	Expect(testEnv.Stop()).To(Succeed())
})

// getFirstFoundEnvTestBinaryDir returns the first envtest binary directory under
// bin/k8s, which `make setup-envtest` populates. Returns "" if none is present.
func getFirstFoundEnvTestBinaryDir() string {
	basePath := filepath.Join("..", "..", "bin", "k8s")
	entries, err := os.ReadDir(basePath)
	if err != nil {
		logf.Log.Error(err, "Failed to read directory", "path", basePath)
		return ""
	}
	for _, entry := range entries {
		if entry.IsDir() {
			return filepath.Join(basePath, entry.Name())
		}
	}
	return ""
}

package cache

import (
	"fmt"
	"time"

	"github.com/Infisical/infisical-issuer/internal/model"
	"github.com/dgraph-io/ristretto/v2"
)

type ClientCacheKey struct {
	Name      string
	Namespace string
	// Generation is the issuer's metadata.generation, so an in-place spec edit
	// yields a new key and never reuses a stale token.
	Generation int64
}

func (k ClientCacheKey) String() string {
	return fmt.Sprintf("%s/%s/%d", k.Namespace, k.Name, k.Generation)
}

type AuthCache struct {
	cache           *ristretto.Cache[string, *model.AuthenticationResult]
	minTTLThreshold time.Duration
}

type AuthCacheOption func(*AuthCache)

func WithMinTTLThreshold(minTTL time.Duration) AuthCacheOption {
	return func(ac *AuthCache) {
		ac.minTTLThreshold = minTTL
	}
}

func NewAuthCache(opts ...AuthCacheOption) (*AuthCache, error) {
	c, err := ristretto.NewCache(&ristretto.Config[string, *model.AuthenticationResult]{
		NumCounters:        1000,
		MaxCost:            1 << 30,
		BufferItems:        64,
		IgnoreInternalCost: true,
	})
	if err != nil {
		return nil, fmt.Errorf("failed to create auth cache: %w", err)
	}
	ac := &AuthCache{cache: c}
	for _, opt := range opts {
		opt(ac)
	}
	return ac, nil
}

func (c *AuthCache) Get(key ClientCacheKey) (*model.AuthenticationResult, bool) {
	return c.cache.Get(key.String())
}

// Set caches the result and reports whether it was stored. A non-positive TTL is
// rejected (ristretto treats ttl==0 as no-expiry), as is a TTL below minTTLThreshold.
func (c *AuthCache) Set(key ClientCacheKey, value *model.AuthenticationResult, ttl time.Duration) bool {
	if ttl <= 0 || ttl < c.minTTLThreshold {
		return false
	}
	c.cache.SetWithTTL(key.String(), value, 1, ttl)
	c.cache.Wait()
	return true
}

func (c *AuthCache) Delete(key ClientCacheKey) {
	c.cache.Del(key.String())
}

func (c *AuthCache) Cleanup() {
	if c.cache != nil {
		c.cache.Close()
	}
}

package util_test

import (
	"context"
	"strings"
	"testing"

	corev1 "k8s.io/api/core/v1"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/runtime"
	"sigs.k8s.io/controller-runtime/pkg/client/fake"

	"github.com/Infisical/infisical-issuer/api/v1alpha1"
	"github.com/Infisical/infisical-issuer/internal/util"
)

func newClientWithSecret(namespace string) *corev1.Secret {
	return &corev1.Secret{
		ObjectMeta: metav1.ObjectMeta{Name: "creds", Namespace: namespace},
		Data:       map[string][]byte{"value": []byte("secret-data")},
	}
}

func TestResolveSecretReferenceConfinement(t *testing.T) {
	scheme := runtime.NewScheme()
	if err := corev1.AddToScheme(scheme); err != nil {
		t.Fatalf("add corev1 to scheme: %v", err)
	}
	c := fake.NewClientBuilder().WithScheme(scheme).WithObjects(newClientWithSecret("team-a")).Build()
	ctx := context.Background()

	t.Run("resolves a reference within the resource namespace", func(t *testing.T) {
		ref := v1alpha1.SecretReference{Name: "creds", Namespace: "team-a", Key: "value"}
		val, err := util.ResolveSecretReference(ctx, c, ref, "team-a", "field")
		if err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		if val != "secret-data" {
			t.Fatalf("got %q, want %q", val, "secret-data")
		}
	})

	t.Run("defaults to the resource namespace when the reference omits it", func(t *testing.T) {
		ref := v1alpha1.SecretReference{Name: "creds", Key: "value"}
		val, err := util.ResolveSecretReference(ctx, c, ref, "team-a", "field")
		if err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		if val != "secret-data" {
			t.Fatalf("got %q, want %q", val, "secret-data")
		}
	})

	t.Run("rejects a reference to a foreign namespace", func(t *testing.T) {
		// A namespaced Issuer in team-a must not be able to read team-b's Secret.
		ref := v1alpha1.SecretReference{Name: "creds", Namespace: "team-b", Key: "value"}
		_, err := util.ResolveSecretReference(ctx, c, ref, "team-a", "field")
		if err == nil {
			t.Fatal("expected a cross-namespace reference to be rejected, got nil")
		}
		if got := err.Error(); !strings.Contains(got, "cross-namespace references are not allowed") {
			t.Fatalf("error %q does not mention the cross-namespace rejection", got)
		}
	})
}
